import sys, time, html, requests
sys.stdout.reconfigure(encoding="utf-8")
from PIL import Image
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.common.keys import Keys
D="docs/scratch/video/"; O="docs/scratch/star/crops/"
r=requests.post("http://localhost:5001/api/chatbot",json={"message":"Combien de compagnies ont un ratio combiné inférieur à 100 % en 2024 ?","session_id":"sqlcard1"},timeout=120).json()
sql=(r.get("data") or {}).get("sql","").strip(); print(sql)
base="""<html><head><meta charset='utf-8'><style>body{margin:0;background:#fff;font-family:'Segoe UI',Arial,sans-serif}.c{width:%dpx;box-sizing:border-box;border:1px solid #e3e6ee;border-radius:14px;padding:22px 26px;background:#fff}
.k{font-size:11px;letter-spacing:1.6px;color:#8b8b90;font-weight:700;text-transform:uppercase;margin-bottom:10px}pre{margin:0;background:#2F3136;color:#f2f2f4;border-radius:10px;padding:16px 18px;font:14px/1.5 Consolas,monospace;white-space:pre-wrap}
.row{display:flex;gap:14px;align-items:stretch;margin-bottom:10px}.box{flex:1;border:1px solid #e3e6ee;border-radius:10px;padding:12px 14px;background:#f7f8fb}.box b{display:block;font-size:11px;letter-spacing:1.4px;color:#8b8b90;text-transform:uppercase;margin-bottom:6px}.box span{font-size:16px;font-weight:700;color:#26282f}
.arrow{align-self:center;font-size:22px;color:#b9b9c0}.gold{background:#FFE600;border-color:#FFE600}.gold b{color:#484B54}
.bar{height:26px;border-radius:6px;display:flex;align-items:center;padding-left:10px;font-weight:700;font-size:13px;color:#fff}.lab{font-size:14px;font-weight:700;color:#26282f;margin:12px 0 5px}.sm{font-size:12.5px;color:#5a5d66}
</style></head><body>%s</body></html>"""
sqlcard=base%(620,"<div id='c' class='c'><div class='k'>SQL generated by the LLM</div><pre>%s</pre></div>"%html.escape(sql))
router=base%(1000,"""<div id='c' class='c'><div class='k'>Question analysis · real output</div>
<div class='row'><div class='box' style='flex:2.2'><b>Question</b><span>Quel sera le résultat net de STAR en 2026 ?</span></div></div>
<div class='row'><div class='box'><b>KPI</b><span>Résultat Net</span></div><div class='box'><b>Company</b><span>STAR</span></div><div class='box'><b>Year</b><span>2026</span></div></div>
<div class='row'><div class='box'><b>Rule</b><span>year &gt; 2024 (last known)</span></div><div class='arrow'>→</div><div class='box'><b>Intent</b><span>forecast</span></div><div class='arrow'>→</div><div class='box gold'><b>Engine</b><span>XGBoost vs Prophet</span></div></div></div>""")
comp=base%(1000,"""<div id='c' class='c'><div class='k'>Model competition · Résultat Net · STAR · time-series cross-validation (8 folds)</div>
<div class='lab'>XGBoost &nbsp;<span style='color:#0f7b43'>✓ selected</span></div><div class='bar' style='width:18%;background:#484B54'>MAPE 18,1 %</div><div class='sm'>RMSE 5,31 · score 13,0</div>
<div class='lab'>Prophet</div><div class='bar' style='width:96%;background:#b9b9c0;color:#26282f'>MAPE 96,5 %</div><div class='sm'>RMSE 23,69 · score 67,8</div>
<div class='lab' style='margin-top:18px'>Forecast 2026 (winner) : <span style='background:#FFE600;padding:2px 10px;border-radius:6px'>31,59 MDT</span></div></div>""")
for n,h in (("ai_sqlcard",sqlcard),("ai_router",router),("ai_comp",comp)): open(D+n+".html","w",encoding="utf-8").write(h)
o=webdriver.ChromeOptions(); o.add_argument("--headless=new"); o.add_argument("--window-size=1200,900"); o.add_argument("--hide-scrollbars"); o.add_argument("--force-device-scale-factor=2")
d=webdriver.Chrome(options=o)
try:
    for n in ("ai_sqlcard","ai_router","ai_comp"):
        d.get("file:///C:/Users/HP/Desktop/SCRAPING/docs/scratch/video/%s.html"%n); time.sleep(.8); d.find_element(By.ID,"c").screenshot(O+n+".png")
    # UI shots
    def shot(name,q,wait=28):
        d.get("http://localhost:5173/"); time.sleep(6); d.execute_script("localStorage.clear()")
        d.find_element(By.CSS_SELECTOR,"button[title='Assistant IA']").click(); time.sleep(1.5)
        i=d.find_element(By.CSS_SELECTOR,"input.chat-input,textarea.chat-input"); i.click(); i.send_keys(q); i.send_keys(Keys.ENTER); time.sleep(wait)
        d.execute_script("""const sc=document.querySelector('.chat-scroll');let p=sc.parentElement;p.style.height='1000px';p.style.maxHeight='1000px';""")
        time.sleep(.5)
        d.execute_script("""const s=document.querySelector('.chat-scroll');const els=[...s.querySelectorAll('*')].filter(e=>e.children.length==0&&e.textContent.trim()==='VOUS');els[els.length-1].scrollIntoView({block:'start'});s.scrollTop-=14;""")
        time.sleep(1); d.find_element(By.CSS_SELECTOR,".chat-scroll").find_element(By.XPATH,"./..").screenshot(O+name+".png")
    shot("ai_agrement","Qui délivre l'agrément aux compagnies d'assurance en Tunisie ?")
    shot("ai_sql","Combien de compagnies ont un ratio combiné inférieur à 100 % en 2024 ?")
finally: d.quit()
for n in ("ai_sqlcard","ai_router","ai_comp","ai_agrement","ai_sql"): print(n,Image.open(O+n+".png").size)
